new='''uint32_t selectedSkin=frameProvider.initialSkin,selectedBody=frameProvider.initialBody;auto selectionOption=[&](const char*name,uint32_t&value){char text[32]{};auto size=GetEnvironmentVariableA(name,text,sizeof(text));if(!size)return;if(size>=sizeof(text)||frameProvider.sample)throw std::runtime_error("invalid or conflicting diagnostic model selection");auto parsed=std::from_chars(text,text+size,value);if(parsed.ec!=std::errc{}||parsed.ptr!=text+size)throw std::runtime_error("diagnostic model selection value");};selectionOption("SFM64_DIAGNOSTIC_MODEL_SKIN",selectedSkin);selectionOption("SFM64_DIAGNOSTIC_MODEL_BODY",selectedBody);auto renderInputs=prepareModelRenderInputsCandidate(model,selectedSkin,{mount.parent_path()},2,modelBodySelectionCandidate(selectedBody,model.bodyModelCounts,model.bodyBases));std::cout<<"model_selection skin="<<selectedSkin<<" body="<<selectedBody<<" triangles="<<renderInputs.indices.size()/3<<"\\n";'''
assert s.count(old)==1;s=s.replace(old,new);p.write_text(s)
